"""Generate static/tokens.css from design/tokens.json (protected core, ADR 0005).

Usage:
    python scripts/build_tokens.py --write   (re)generate tokens.css
    python scripts/build_tokens.py           verify tokens.css is fresh (exit 1 if so)
    python scripts/build_tokens.py --check   same as default
"""

from __future__ import annotations

import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TOKENS_PATH = ROOT / "design" / "tokens.json"
OUT_PATH = ROOT / "src" / "factory" / "static" / "tokens.css"

HEADER = (
    "/* Generated by scripts/build_tokens.py from design/tokens.json. Do not edit. */\n"
)


def build_tokens_css(tokens: dict) -> str:
    lines = [HEADER, ":root {", "  color-scheme: light dark;"]
    for key, value in tokens["color"]["light"].items():
        lines.append(f"  --c-{key.replace('-', '_')}: {value};")
    lines.append(f"  --font-sans: {tokens['font']['sans']};")
    lines.append(f"  --font-mono: {tokens['font']['mono']};")
    for group in ("size", "space", "radius", "layout"):
        for key, value in tokens[group].items():
            lines.append(f"  --{group}-{key.replace('-', '_')}: {value};")
    lines.append("}")
    lines.append("")
    lines.append("@media (prefers-color-scheme: dark) {")
    lines.append("  :root {")
    for key, value in tokens["color"]["dark"].items():
        lines.append(f"    --c-{key.replace('-', '_')}: {value};")
    lines.append("    color-scheme: dark;")
    lines.append("  }")
    lines.append("}")
    lines.append("")
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("--write", action="store_true", help="write tokens.css")
    group.add_argument(
        "--check", action="store_true", help="fail if tokens.css is stale"
    )
    args = parser.parse_args()

    tokens = json.loads(TOKENS_PATH.read_text(encoding="utf-8"))
    generated = build_tokens_css(tokens)

    if args.write:
        OUT_PATH.write_text(generated, encoding="utf-8")
        print(f"build_tokens: wrote {OUT_PATH.relative_to(ROOT)}")
        return 0
    if not OUT_PATH.exists():
        print(
            "error: static/tokens.css is missing; run scripts/build_tokens.py --write"
        )
        return 1
    committed = OUT_PATH.read_text(encoding="utf-8")
    if committed != generated:
        print("error: static/tokens.css is stale; run scripts/build_tokens.py --write")
        return 1
    print("build_tokens: ok")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
